<?php
use Illuminate\Support\Facades\Route;
use Modules\EggManagement\Http\Controllers\DashboardController;
use Modules\EggManagement\Http\Controllers\GradeController;
use Modules\EggManagement\Http\Controllers\FlockController;
use Modules\EggManagement\Http\Controllers\ProductionController;
use Modules\EggManagement\Http\Controllers\GradingController;
use Modules\EggManagement\Http\Controllers\StockController;
use Modules\EggManagement\Http\Controllers\SaleController;
use Modules\EggManagement\Http\Controllers\PurchaseController;
use Modules\EggManagement\Http\Controllers\TransferController;
use Modules\EggManagement\Http\Controllers\AdjustmentController;
use Modules\EggManagement\Http\Controllers\IntegrationController;
use Modules\EggManagement\Http\Controllers\ShareController;
use Modules\EggManagement\Http\Controllers\ProductMappingController;
use Modules\EggManagement\Http\Controllers\SettingsController;
use Modules\EggManagement\Http\Controllers\Reports\ReportsController;
use Modules\EggManagement\Http\Controllers\Reports\ProductionReportController;
use Modules\EggManagement\Http\Controllers\Reports\StockReportController;
use Modules\EggManagement\Http\Controllers\Reports\SalesReportController;
use Modules\EggManagement\Http\Controllers\Reports\PurchaseReportController;
use Modules\EggManagement\Http\Controllers\Reports\MovementReportController;
use Modules\EggManagement\Http\Controllers\Reports\WastageReportController;
use Modules\EggManagement\Http\Controllers\Reports\AuditReportController;

Route::group(['prefix'=>config('egg.route_prefix','egg-management'),'as'=>'egg.','middleware'=>config('egg.middleware',['web','auth'])], function(){
    Route::get('/',[DashboardController::class,'index'])->middleware('egg.permission:egg.dashboard.view')->name('dashboard');
    Route::get('flocks',[FlockController::class,'index'])->middleware('egg.permission:egg.flocks.view')->name('flocks.index');
    Route::get('flocks/create',[FlockController::class,'create'])->middleware('egg.permission:egg.flocks.create')->name('flocks.create');
    Route::post('flocks',[FlockController::class,'store'])->middleware('egg.permission:egg.flocks.create')->name('flocks.store');
    Route::get('production',[ProductionController::class,'index'])->middleware('egg.permission:egg.production.view')->name('production.index');
    Route::get('production/create',[ProductionController::class,'create'])->middleware('egg.permission:egg.production.create')->name('production.create');
    Route::post('production',[ProductionController::class,'store'])->middleware('egg.permission:egg.production.create')->name('production.store');
    Route::get('grading',[GradingController::class,'index'])->middleware('egg.permission:egg.grading.view')->name('grading.index');
    Route::get('grading/create',[GradingController::class,'create'])->middleware('egg.permission:egg.grading.create')->name('grading.create');
    Route::post('grading',[GradingController::class,'store'])->middleware('egg.permission:egg.grading.create')->name('grading.store');
    Route::get('stock',[StockController::class,'index'])->middleware('egg.permission:egg.stock.view')->name('stock.index');
    Route::get('sales',[SaleController::class,'index'])->middleware('egg.permission:egg.sales.view')->name('sales.index');
    Route::get('sales/create',[SaleController::class,'create'])->middleware('egg.permission:egg.sales.create')->name('sales.create');
    Route::post('sales',[SaleController::class,'store'])->middleware('egg.permission:egg.sales.create')->name('sales.store');
    Route::get('purchases',[PurchaseController::class,'index'])->middleware('egg.permission:egg.purchases.view')->name('purchases.index');
    Route::get('purchases/create',[PurchaseController::class,'create'])->middleware('egg.permission:egg.purchases.create')->name('purchases.create');
    Route::post('purchases',[PurchaseController::class,'store'])->middleware('egg.permission:egg.purchases.create')->name('purchases.store');
    Route::get('transfers',[TransferController::class,'index'])->middleware('egg.permission:egg.transfers.view')->name('transfers.index');
    Route::get('transfers/create',[TransferController::class,'create'])->middleware('egg.permission:egg.transfers.create')->name('transfers.create');
    Route::post('transfers',[TransferController::class,'store'])->middleware('egg.permission:egg.transfers.create')->name('transfers.store');
    Route::get('adjustments',[AdjustmentController::class,'index'])->middleware('egg.permission:egg.adjustments.view')->name('adjustments.index');
    Route::get('adjustments/create',[AdjustmentController::class,'create'])->middleware('egg.permission:egg.adjustments.create')->name('adjustments.create');
    Route::post('adjustments',[AdjustmentController::class,'store'])->middleware('egg.permission:egg.adjustments.create')->name('adjustments.store');
    Route::get('settings',[SettingsController::class,'index'])->middleware('egg.permission:egg.settings.view')->name('settings.index');
    Route::get('settings/grades',[GradeController::class,'index'])->middleware('egg.permission:egg.settings.view')->name('grades.index');
    Route::post('settings/grades',[GradeController::class,'store'])->middleware('egg.permission:egg.settings.manage')->name('grades.store');
    Route::post('settings/grades/{grade}/toggle',[GradeController::class,'toggle'])->middleware('egg.permission:egg.settings.manage')->name('grades.toggle');
    Route::get('settings/product-mappings',[ProductMappingController::class,'index'])->middleware('egg.permission:egg.product-mappings.view')->name('product-mappings.index');
    Route::post('settings/product-mappings',[ProductMappingController::class,'store'])->middleware('egg.permission:egg.product-mappings.manage')->name('product-mappings.store');
    Route::delete('settings/product-mappings/{mapping}',[ProductMappingController::class,'destroy'])->middleware('egg.permission:egg.product-mappings.manage')->name('product-mappings.destroy');
    Route::get('integrations',[IntegrationController::class,'index'])->middleware('egg.permission:egg.integrations.view')->name('integrations.index');
    Route::post('share',[ShareController::class,'create'])->middleware('egg.permission:egg.share')->name('share.create');

    Route::prefix('reports')->as('reports.')->group(function(){
        Route::get('/',[ReportsController::class,'index'])->name('index');
        Route::get('production',[ProductionReportController::class,'index'])->middleware('egg.permission:egg.reports.production')->name('production');
        Route::get('stock',[StockReportController::class,'index'])->middleware('egg.permission:egg.reports.stock')->name('stock');
        Route::get('sales',[SalesReportController::class,'index'])->middleware('egg.permission:egg.reports.sales')->name('sales');
        Route::get('purchases',[PurchaseReportController::class,'index'])->middleware('egg.permission:egg.reports.purchases')->name('purchases');
        Route::get('movements',[MovementReportController::class,'index'])->middleware('egg.permission:egg.reports.movements')->name('movements');
        Route::get('wastage',[WastageReportController::class,'index'])->middleware('egg.permission:egg.reports.wastage')->name('wastage');
        Route::get('audit',[AuditReportController::class,'index'])->middleware('egg.permission:egg.reports.audit')->name('audit');
    });
});
